// seedAdoptPair puts two items in ONE fresh library — a tombstoned source
// (status 'deleted', the state adoption reads the dead rows from) and a live
// successor — and returns both ids. Playback_progress rows are written
// through PutProgress (the real write path, CHECK-guarded); ledger rows go
// through InsertWatched (same), with applied_at stamped directly where a test
// needs an APPLIED completion (the learning queue's stamp).
func seedAdoptPair(t *testing.T, s *Store) (fromID, toID string, libID int64) {
	t.Helper()
	ctx := context.Background()
	var err error
	libID, err = s.CreateLibrary(ctx, "tv", "/media/adopt", "TV")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	fromID, toID = "itm_adopt_dead", "itm_adopt_live"
	for _, it := range []Item{
		{ID: fromID, ModuleID: "tv", LibraryID: libID, FileID: "dead.mkv",
			RelativePath: "dead.mkv", MediaType: "tv", Status: "deleted",
			Document: json.RawMessage(`{}`), SchemaVersion: 1},
		{ID: toID, ModuleID: "tv", LibraryID: libID, FileID: "live.mkv",
			RelativePath: "live.mkv", MediaType: "tv",
			Document: json.RawMessage(`{}`), SchemaVersion: 1},
	} {
		if err := s.PutItem(ctx, it); err != nil {
			t.Fatalf("PutItem %s: %v", it.ID, err)
		}
	}
	return fromID, toID, libID
}

// progressRow reads one playback_progress row (position, stamp) or reports it
// absent — the assertion helper for slot-state checks.
func progressRow(t *testing.T, s *Store, userID int64, itemID string) (position int64, updated string, present bool) {
	t.Helper()
	err := s.db.QueryRowContext(context.Background(),
		"SELECT position_seconds, updated_at FROM playback_progress WHERE user_id = ? AND item_id = ?",
		userID, itemID).Scan(&position, &updated)
	if err != nil {
		return 0, "", false
	}
	return position, updated, true
}

// TestMoveItemProgress covers the playback-progress adoption move
// (tombstone-lifecycle D5): absent slots receive the source row verbatim, the
// live item's own rows win their slots (positive AND zero-position alike),
// source rows are deleted either way, and a re-run moves nothing.
func TestMoveItemProgress(t *testing.T) {
	ctx := context.Background()

	t.Run("moves into absent slots and deletes source", func(t *testing.T) {
		s := openStore(t)
		fromID, toID, libID := seedAdoptPair(t, s)
		if _, err := s.PutProgress(ctx, fromID, 720, access.System()); err != nil {
			t.Fatalf("PutProgress source: %v", err)
		}
		user5 := access.User(5, []int64{libID}, nil)
		if _, err := s.PutProgress(ctx, fromID, 300, user5); err != nil {
			t.Fatalf("PutProgress user5: %v", err)
		}

		n, err := s.MoveItemProgress(ctx, fromID, toID)
		if err != nil {
			t.Fatalf("MoveItemProgress: %v", err)
		}
		if n != 2 {
			t.Fatalf("moved = %d, want 2", n)
		}
		for _, tc := range []struct {
			userID int64
			pos    int64
		}{{0, 720}, {5, 300}} {
			pos, _, ok := progressRow(t, s, tc.userID, toID)
			if !ok || pos != tc.pos {
				t.Fatalf("target slot %d: (pos=%d present=%v), want pos %d", tc.userID, pos, ok, tc.pos)
			}
		}
		var left int
		if err := s.db.QueryRowContext(ctx,
			"SELECT COUNT(*) FROM playback_progress WHERE item_id = ?", fromID).Scan(&left); err != nil {
			t.Fatalf("count source rows: %v", err)
		}
		if left != 0 {
			t.Fatalf("source rows left = %d, want 0", left)
		}
	})

	t.Run("live row wins the slot", func(t *testing.T) {
		s := openStore(t)
		fromID, toID, _ := seedAdoptPair(t, s)
		if _, err := s.PutProgress(ctx, fromID, 42, access.System()); err != nil {
			t.Fatalf("PutProgress source: %v", err)
		}
		if _, err := s.PutProgress(ctx, toID, 999, access.System()); err != nil {
			t.Fatalf("PutProgress target: %v", err)
		}

		n, err := s.MoveItemProgress(ctx, fromID, toID)
		if err != nil {
			t.Fatalf("MoveItemProgress: %v", err)
		}
		if n != 0 {
			t.Fatalf("moved = %d, want 0 (live row wins)", n)
		}
		pos, _, ok := progressRow(t, s, 0, toID)
		if !ok || pos != 999 {
			t.Fatalf("target slot: (pos=%d present=%v), want live row's 999", pos, ok)
		}
		var left int
		if err := s.db.QueryRowContext(ctx,
			"SELECT COUNT(*) FROM playback_progress WHERE item_id = ?", fromID).Scan(&left); err != nil {
			t.Fatalf("count source rows: %v", err)
		}
		if left != 0 {
			t.Fatalf("source rows left = %d, want 0 (no ghost stock)", left)
		}
	})

	t.Run("zero-position slot wins", func(t *testing.T) {
		s := openStore(t)
		fromID, toID, _ := seedAdoptPair(t, s)
		if _, err := s.PutProgress(ctx, fromID, 500, access.System()); err != nil {
			t.Fatalf("PutProgress source: %v", err)
		}
		// The explicit unwatched-reset slot on the LIVE item: a 0 the viewer
		// wrote via the unwatch path — adoption must not resurrect over it.
		if _, err := s.PutProgress(ctx, toID, 0, access.System()); err != nil {
			t.Fatalf("PutProgress zero reset: %v", err)
		}

		n, err := s.MoveItemProgress(ctx, fromID, toID)
		if err != nil {
			t.Fatalf("MoveItemProgress: %v", err)
		}
		if n != 0 {
			t.Fatalf("moved = %d, want 0 (zero-position slot wins)", n)
		}
		pos, _, ok := progressRow(t, s, 0, toID)
		if !ok || pos != 0 {
			t.Fatalf("target slot: (pos=%d present=%v), want the reset 0", pos, ok)
		}
	})

	t.Run("per-viewer conflict suppresses only that viewer", func(t *testing.T) {
		s := openStore(t)
		fromID, toID, libID := seedAdoptPair(t, s)
		if _, err := s.PutProgress(ctx, fromID, 60, access.System()); err != nil {
			t.Fatalf("PutProgress source slot0: %v", err)
		}
		user5 := access.User(5, []int64{libID}, nil)
		if _, err := s.PutProgress(ctx, fromID, 120, user5); err != nil {
			t.Fatalf("PutProgress source user5: %v", err)
		}
		if _, err := s.PutProgress(ctx, toID, 240, access.System()); err != nil {
			t.Fatalf("PutProgress target slot0: %v", err)
		}

		n, err := s.MoveItemProgress(ctx, fromID, toID)
		if err != nil {
			t.Fatalf("MoveItemProgress: %v", err)
		}
		if n != 1 {
			t.Fatalf("moved = %d, want 1 (only user5's slot was absent)", n)
		}
		if pos, _, ok := progressRow(t, s, 5, toID); !ok || pos != 120 {
			t.Fatalf("user5 moved row: (pos=%d present=%v), want 120", pos, ok)
		}
		if pos, _, _ := progressRow(t, s, 0, toID); pos != 240 {
			t.Fatalf("target slot0 pos = %d, want live row's 240", pos)
		}
	})

	t.Run("re-run is a no-op", func(t *testing.T) {
		s := openStore(t)
		fromID, toID, _ := seedAdoptPair(t, s)
		if _, err := s.PutProgress(ctx, fromID, 42, access.System()); err != nil {
			t.Fatalf("PutProgress: %v", err)
		}
		if n, err := s.MoveItemProgress(ctx, fromID, toID); err != nil || n != 1 {
			t.Fatalf("first move: n=%d err=%v, want n=1 nil", n, err)
		}
		n, err := s.MoveItemProgress(ctx, fromID, toID)
		if err != nil {
			t.Fatalf("second move: %v", err)
		}
		if n != 0 {
			t.Fatalf("second move moved = %d, want 0", n)
		}
		if pos, _, ok := progressRow(t, s, 0, toID); !ok || pos != 42 {
			t.Fatalf("target row after re-run: (pos=%d present=%v), want verbatim 42", pos, ok)
		}
	})
}

// adoptLedgerRow reads one watched_items ledger row (path, completed, applied)
// or reports it absent — the assertion helper for ledger-state checks.
// series_relative_path is nullable (NULL for film/tv), so it scans through
// sql.NullString; applied_at surfaces as any (nil = NULL, the learning queue).
func adoptLedgerRow(t *testing.T, s *Store, userID int64, itemID string) (seriesPath string, completed string, applied any, present bool) {
	t.Helper()
	var nullPath sql.NullString
	err := s.db.QueryRowContext(context.Background(),
		"SELECT series_relative_path, completed_at, applied_at FROM watched_items WHERE user_id = ? AND item_id = ?",
		userID, itemID).Scan(&nullPath, &completed, &applied)
	if err != nil {
		return "", "", nil, false
	}
	return nullPath.String, completed, applied, true
}

// TestMoveItemWatched covers the completion-ledger adoption move
// (tombstone-lifecycle D5): completed_at/applied_at carry verbatim,
// series_relative_path re-points only on a non-empty seriesPath, the live
// item's ledger row wins its slot, source rows are deleted, and a re-run
// moves nothing.
func TestMoveItemWatched(t *testing.T) {
	ctx := context.Background()

	t.Run("moves verbatim stamps and re-points seriesPath", func(t *testing.T) {
		s := openStore(t)
		fromID, toID, libID := seedAdoptPair(t, s)
		completed := time.Date(2026, 11, 1, 12, 0, 0, 0, time.UTC)
		if err := s.InsertWatched(ctx, fromID, libID, "series/old", completed, access.System()); err != nil {
			t.Fatalf("InsertWatched: %v", err)
		}
		appliedStamp := "2026-11-02T00:00:00Z"
		if _, err := s.db.ExecContext(ctx,
			"UPDATE watched_items SET applied_at = ? WHERE item_id = ?", appliedStamp, fromID); err != nil {
			t.Fatalf("stamp applied_at: %v", err)
		}

		n, err := s.MoveItemWatched(ctx, fromID, toID, "series/new")
		if err != nil {
			t.Fatalf("MoveItemWatched: %v", err)
		}
		if n != 1 {
			t.Fatalf("moved = %d, want 1", n)
		}
		path, gotCompleted, applied, ok := adoptLedgerRow(t, s, 0, toID)
		if !ok {
			t.Fatal("target ledger row absent, want present")
		}
		if path != "series/new" {
			t.Fatalf("series_relative_path = %q, want re-pointed %q", path, "series/new")
		}
		if gotCompleted != formatTime(completed) {
			t.Fatalf("completed_at = %q, want verbatim %q", gotCompleted, formatTime(completed))
		}
		if applied != any(appliedStamp) {
			t.Fatalf("applied_at = %v, want verbatim %q", applied, appliedStamp)
		}
		var left int
		if err := s.db.QueryRowContext(ctx,
			"SELECT COUNT(*) FROM watched_items WHERE item_id = ?", fromID).Scan(&left); err != nil {
			t.Fatalf("count source rows: %v", err)
		}
		if left != 0 {
			t.Fatalf("source rows left = %d, want 0", left)
		}
	})

	t.Run("empty seriesPath keeps the source value", func(t *testing.T) {
		s := openStore(t)
		fromID, toID, libID := seedAdoptPair(t, s)
		if err := s.InsertWatched(ctx, fromID, libID, "series/kept", time.Now(), access.System()); err != nil {
			t.Fatalf("InsertWatched: %v", err)
		}

		if n, err := s.MoveItemWatched(ctx, fromID, toID, ""); err != nil || n != 1 {
			t.Fatalf("move: n=%d err=%v, want n=1 nil", n, err)
		}
		path, _, _, ok := adoptLedgerRow(t, s, 0, toID)
		if !ok || path != "series/kept" {
			t.Fatalf("series_relative_path = (%q present=%v), want source %q", path, ok, "series/kept")
		}
	})

	t.Run("unapplied row moves with NULL applied_at", func(t *testing.T) {
		s := openStore(t)
		fromID, toID, libID := seedAdoptPair(t, s)
		if err := s.InsertWatched(ctx, fromID, libID, "", time.Now(), access.System()); err != nil {
			t.Fatalf("InsertWatched: %v", err)
		}

		if n, err := s.MoveItemWatched(ctx, fromID, toID, ""); err != nil || n != 1 {
			t.Fatalf("move: n=%d err=%v, want n=1 nil", n, err)
		}
		_, _, applied, ok := adoptLedgerRow(t, s, 0, toID)
		if !ok || applied != nil {
			t.Fatalf("applied_at = (%v present=%v), want NULL carried verbatim", applied, ok)
		}
	})

	t.Run("live ledger row wins the slot", func(t *testing.T) {
		s := openStore(t)
		fromID, toID, libID := seedAdoptPair(t, s)
		if err := s.InsertWatched(ctx, fromID, libID, "series/old", time.Date(2026, 11, 1, 0, 0, 0, 0, time.UTC), access.System()); err != nil {
			t.Fatalf("InsertWatched source: %v", err)
		}
		liveCompleted := time.Date(2026, 11, 8, 0, 0, 0, 0, time.UTC)
		if err := s.InsertWatched(ctx, toID, libID, "series/live", liveCompleted, access.System()); err != nil {
			t.Fatalf("InsertWatched target: %v", err)
		}

		n, err := s.MoveItemWatched(ctx, fromID, toID, "series/new")
		if err != nil {
			t.Fatalf("MoveItemWatched: %v", err)
		}
		if n != 0 {
			t.Fatalf("moved = %d, want 0 (live row wins)", n)
		}
		path, completed, _, ok := adoptLedgerRow(t, s, 0, toID)
		if !ok || path != "series/live" || completed != "2026-11-08T00:00:00Z" {
			t.Fatalf("target row = (path=%q completed=%q present=%v), want live row untouched", path, completed, ok)
		}
		var left int
		if err := s.db.QueryRowContext(ctx,
			"SELECT COUNT(*) FROM watched_items WHERE item_id = ?", fromID).Scan(&left); err != nil {
			t.Fatalf("count source rows: %v", err)
		}
		if left != 0 {
			t.Fatalf("source rows left = %d, want 0 (no ghost stock)", left)
		}
	})

	t.Run("counts reflect moved rows per viewer", func(t *testing.T) {
		s := openStore(t)
		fromID, toID, libID := seedAdoptPair(t, s)
		completed := time.Now()
		if err := s.InsertWatched(ctx, fromID, libID, "series/x", completed, access.System()); err != nil {
			t.Fatalf("InsertWatched slot0: %v", err)
		}
		if err := s.InsertWatched(ctx, fromID, libID, "series/x", completed, access.User(7, []int64{libID}, nil)); err != nil {
			t.Fatalf("InsertWatched user7: %v", err)
		}
		if err := s.InsertWatched(ctx, toID, libID, "series/y", completed, access.User(7, []int64{libID}, nil)); err != nil {
			t.Fatalf("InsertWatched target user7: %v", err)
		}

		n, err := s.MoveItemWatched(ctx, fromID, toID, "series/z")
		if err != nil {
			t.Fatalf("MoveItemWatched: %v", err)
		}
		if n != 1 {
			t.Fatalf("moved = %d, want 1 (only slot0 was absent at target)", n)
		}
	})

	t.Run("re-run is a no-op", func(t *testing.T) {
		s := openStore(t)
		fromID, toID, libID := seedAdoptPair(t, s)
		if err := s.InsertWatched(ctx, fromID, libID, "series/old", time.Now(), access.System()); err != nil {
			t.Fatalf("InsertWatched: %v", err)
		}
		if n, err := s.MoveItemWatched(ctx, fromID, toID, "series/new"); err != nil || n != 1 {
			t.Fatalf("first move: n=%d err=%v, want n=1 nil", n, err)
		}
		n, err := s.MoveItemWatched(ctx, fromID, toID, "series/new")
		if err != nil {
			t.Fatalf("second move: %v", err)
		}
		if n != 0 {
			t.Fatalf("second move moved = %d, want 0", n)
		}
	})
}

// TestMoveItemProgressSelfMoveIsNoOp pins the self-move guard (task 2.6): a
// from == to move returns (0, nil) BEFORE any transaction and the id's stock
// survives byte-intact — the self-move's NOT EXISTS insert would add nothing,
// but the unconditional DELETE would destroy the id's whole retained stock.
func TestMoveItemProgressSelfMoveIsNoOp(t *testing.T) {
	ctx := context.Background()
	s := openStore(t)
	libID, err := s.CreateLibrary(ctx, "tv", "/media/selfmove", "TV")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	id := "itm_selfmove_progress"
	if err := s.PutItem(ctx, Item{
		ID: id, ModuleID: "tv", LibraryID: libID, FileID: "self.mkv",
		RelativePath: "self.mkv", MediaType: "tv", Status: "deleted",
		Document: json.RawMessage(`{}`), SchemaVersion: 1,
	}); err != nil {
		t.Fatalf("PutItem: %v", err)
	}
	if _, err := s.PutProgress(ctx, id, 321, access.System()); err != nil {
		t.Fatalf("PutProgress slot0: %v", err)
	}
	if _, err := s.PutProgress(ctx, id, 654, access.User(5, []int64{libID}, nil)); err != nil {
		t.Fatalf("PutProgress user5: %v", err)
	}

	n, err := s.MoveItemProgress(ctx, id, id)
	if err != nil {
		t.Fatalf("MoveItemProgress self-move: %v", err)
	}
	if n != 0 {
		t.Fatalf("moved = %d, want 0 (no transaction, no deletion)", n)
	}
	if pos, _, ok := progressRow(t, s, 0, id); !ok || pos != 321 {
		t.Fatalf("slot0 stock = (pos=%d present=%v), want verbatim 321", pos, ok)
	}
	if pos, _, ok := progressRow(t, s, 5, id); !ok || pos != 654 {
		t.Fatalf("user5 stock = (pos=%d present=%v), want verbatim 654", pos, ok)
	}
}

// TestMoveItemWatchedSelfMoveIsNoOp pins the watched-ledger self-move guard
// (task 2.6): (0, nil) with no transaction, and the ledger row survives with
// its stamps verbatim and its series_relative_path NOT re-pointed (nothing
// moved, so the move's re-pointing must not touch it either).
func TestMoveItemWatchedSelfMoveIsNoOp(t *testing.T) {
	ctx := context.Background()
	s := openStore(t)
	libID, err := s.CreateLibrary(ctx, "tv", "/media/selfmove-watched", "TV")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	id := "itm_selfmove_watched"
	if err := s.PutItem(ctx, Item{
		ID: id, ModuleID: "tv", LibraryID: libID, FileID: "self.mkv",
		RelativePath: "self.mkv", MediaType: "tv", Status: "deleted",
		Document: json.RawMessage(`{}`), SchemaVersion: 1,
	}); err != nil {
		t.Fatalf("PutItem: %v", err)
	}
	completed := time.Date(2026, 11, 1, 8, 0, 0, 0, time.UTC)
	if err := s.InsertWatched(ctx, id, libID, "series/kept", completed, access.System()); err != nil {
		t.Fatalf("InsertWatched: %v", err)
	}

	n, err := s.MoveItemWatched(ctx, id, id, "series/new")
	if err != nil {
		t.Fatalf("MoveItemWatched self-move: %v", err)
	}
	if n != 0 {
		t.Fatalf("moved = %d, want 0 (no transaction, no deletion)", n)
	}
	path, gotCompleted, _, ok := adoptLedgerRow(t, s, 0, id)
	if !ok {
		t.Fatal("ledger row destroyed by a self-move — the stock must survive")
	}
	if path != "series/kept" {
		t.Fatalf("series_relative_path = %q, want source %q (nothing moved, nothing re-pointed)", path, "series/kept")
	}
	if gotCompleted != formatTime(completed) {
		t.Fatalf("completed_at = %q, want verbatim %q", gotCompleted, formatTime(completed))
	}
}
